    inline bool endpointHasFlag(s16 index, u16 flag) {
        return index >= 0 && index < sEndpointCount && (sEndpoints[index].flags & flag) != 0;
    }

    inline bool isExitOnly(s16 index) { return endpointHasFlag(index, EndpointFlag_ExitOnly); }
    inline bool isEntryOnly(s16 index) { return endpointHasFlag(index, EndpointFlag_EntryOnly); }
    inline bool isOutgoing(s16 index) { return endpointHasFlag(index, EndpointFlag_Outgoing); }

    inline bool behaviorHasDoor(DoorSideBehavior behavior) {
        return behavior == DoorSideBehavior_Door;
    }

    inline bool legacyLinkHasHomeOutDoor(const LegacyLink& link) {
        return behaviorHasDoor(link.homeOutBehavior);
    }

    inline bool legacyLinkHasSubOutDoor(const LegacyLink& link) {
        return behaviorHasDoor(link.subOutBehavior);
    }

    inline const Area* findArea(const char* homeStage, const char* subStage) {
        if (!homeStage || !subStage)
            return nullptr;
        for (s16 i = 0; i < sAreaCount; i++) {
            if (std::strcmp(sAreas[i].homeStage, homeStage) == 0 && std::strcmp(sAreas[i].subStage, subStage) == 0)
                return &sAreas[i];
        }
        return nullptr;
    }

    inline bool endpointSupportsScenario(const Endpoint& endpoint, s32 scenario) {
        return endpoint.scenarioMask == 0
            || (scenario >= 1 && scenario <= 15
                && (endpoint.scenarioMask & (1u << (scenario - 1))) != 0);
    }

    inline const Endpoint* findEndpoint(const char* stage, const char* changeId, const char* targetStage = nullptr) {
        if (!stage || !changeId)
            return nullptr;
        for (s16 i = 0; i < sEndpointCount; i++) {
            const Endpoint& endpoint = sEndpoints[i];
            if (std::strcmp(endpoint.stage, stage) != 0 || std::strcmp(endpoint.changeId, changeId) != 0)
                continue;
            if (targetStage && std::strcmp(endpoint.targetStage, targetStage) != 0)
                continue;
            return &endpoint;
        }
        return nullptr;
    }

    // A ChangeStageId can be authored in multiple scenario layers. Prefer the
    // matching layer, but preserve the first match when none is available so
    // callers can still report or handle a genuinely unavailable entrance.
    inline const Endpoint* findEndpointForScenario(const char* stage, const char* changeId,
        s32 scenario, const char* targetStage = nullptr) {
        if (!stage || !changeId)
            return nullptr;
        const Endpoint* fallback = nullptr;
        for (s16 i = 0; i < sEndpointCount; i++) {
            const Endpoint& endpoint = sEndpoints[i];
            if (std::strcmp(endpoint.stage, stage) != 0 || std::strcmp(endpoint.changeId, changeId) != 0)
                continue;
            if (targetStage && std::strcmp(endpoint.targetStage, targetStage) != 0)
                continue;
            if (!fallback)
                fallback = &endpoint;
            if (endpointSupportsScenario(endpoint, scenario))
                return &endpoint;
        }
        return fallback;
    }

